package jp.personal.hanshinedge.prospective;
import android.content.Context;import org.json.*;import java.time.*;import java.util.*;import jp.personal.hanshinedge.runtime.*;
/** Registration, observation and read models over the EXISTING six audit stores. */
public final class ProspectiveRuntime implements AutoCloseable {
 public static final int[] TARGET={1200,600,300,120},TOLERANCE={180,120,75,45};
 public static final String[] STAGE={"T-20","T-10","T-5","T-2"};
 public static final long CLOCK_LIMIT_MS=10000;
 public static final String STAKE_RULE="NOT_AVAILABLE";
 public final AllVenueRuntime runtime;private final boolean testOnly;
 public ProspectiveRuntime(Context c,String prefix){runtime=new AllVenueRuntime(c,prefix,32*1024*1024);testOnly=prefix.startsWith("test-");}
 public static boolean validRoster(JSONObject registered,JSONObject latest){try{Map<Integer,Boolean> before=new HashMap<>(),after=new HashMap<>();for(int side=0;side<2;side++){JSONObject r=side==0?registered:latest;Map<Integer,Boolean> set=side==0?before:after;JSONArray a=r.getJSONArray("runners");for(int i=0;i<a.length();i++){JSONObject h=a.getJSONObject(i);int no=h.getInt("horse_no");if(no<1||no>18||set.put(no,h.optBoolean("scratched"))!=null)return false;}}if(!before.keySet().equals(after.keySet()))return false;int active=0;for(int no:before.keySet()){if(before.get(no)&&!after.get(no))return false;if(!after.get(no))active++;}return active>=2;}catch(Exception e){return false;}}
 public static long stamp(String s){return OffsetDateTime.parse(s).toInstant().toEpochMilli();}
 public static String canonical(JSONObject r)throws Exception{LocalDate d=LocalDate.parse(r.getString("date"));int v=Integer.parseInt(r.getString("venue_code")),m=r.getInt("meeting"),day=r.getInt("day"),no=r.getInt("race_no");if(v<1||v>10||m<1||m>99||day<1||day>99||no<1||no>12)throw new IllegalArgumentException("RACE_IDENTITY_INVALID");String id=String.format(Locale.ROOT,"%04d%02d%02d%02d%02d",d.getYear(),v,m,day,no);if(r.has("race_id")&&!r.isNull("race_id")&&!id.equals(r.optString("race_id")))throw new IllegalArgumentException("RACE_IDENTITY_MISMATCH");return id;}
 public static JSONObject clock(JSONObject p,long now,long elapsed)throws Exception{long received=p.optLong("received_at_ms",0),server=p.optLong("server_time_ms",0),mono=p.optLong("received_elapsed_ms",-1),delta=elapsed-mono;boolean good=server>0&&received>0&&mono>=0&&delta>=0&&delta<=120000&&Math.abs(received-server)<=CLOCK_LIMIT_MS&&Math.abs(now-(server+delta))<=CLOCK_LIMIT_MS;return new JSONObject().put("verified",good).put("received_at",received).put("server_time",server).put("clock_skew_ms",received-server).put("trusted_now",good?Math.max(now,server+delta):now);}
 public JSONArray rows(String store)throws Exception{JSONArray out=new JSONArray();long after=0;for(int pages=0;pages<10000;pages++){JSONArray page;switch(store){case "FETCH":page=runtime.fetchPage(after);break;case "TIMECHAIN":page=runtime.timechainPage(after);break;case "RESULT":page=runtime.resultPage(after);break;case "SHADOW":page=runtime.shadowPage(after);break;case "FORMAL_BUY":page=runtime.formalBuyPage(after);break;case "SETTLEMENT":page=runtime.settlementPage(after);break;default:throw new IllegalArgumentException("STORE_INVALID");}if(page.length()==0)return out;for(int i=0;i<page.length();i++){JSONObject row=page.getJSONObject(i);out.put(row);after=row.getLong("seq");}}throw new IllegalStateException("STORE_READ_LIMIT");}
 public JSONObject find(String store,String key)throws Exception{JSONArray rows=rows(store);for(int i=0;i<rows.length();i++)if(key.equals(rows.getJSONObject(i).getString("key")))return rows.getJSONObject(i);return null;}
 public JSONObject registration(String id)throws Exception{JSONObject x=find("FETCH","REGISTER:"+id);return x==null?null:new JSONObject(x.getString("payload"));}
 public JSONArray registrations()throws Exception{JSONArray a=rows("FETCH"),out=new JSONArray();for(int i=0;i<a.length();i++){JSONObject p=new JSONObject(a.getJSONObject(i).getString("payload"));if("PROSPECTIVE_REGISTRATION".equals(p.optString("record_type")))out.put(p);}return out;}
 private static final String[] VENUES={"SAPPORO","HAKODATE","FUKUSHIMA","NIIGATA","TOKYO","NAKAYAMA","CHUKYO","KYOTO","HANSHIN","KOKURA"};
 public CapabilityGate.RaceContext context(JSONObject r,boolean prospective,boolean known)throws Exception{return new CapabilityGate.RaceContext(canonical(r),VENUES[Integer.parseInt(r.getString("venue_code"))-1],r.getInt("race_no"),r.optBoolean("obstacle"),prospective,known,CapabilityGate.FROZEN_MODEL);}
 public boolean resultKnown(String id)throws Exception{JSONArray a=rows("RESULT");for(int i=0;i<a.length();i++)if(id.equals(new JSONObject(a.getJSONObject(i).getString("payload")).optString("race_id")))return true;return false;}
 private void proof(JSONObject p)throws Exception{if(!p.optString("raw_sha256").matches("[a-f0-9]{64}")||p.optInt("http_status")!=200||p.optString("source_record_id").isEmpty())throw new IllegalArgumentException("SOURCE_PROOF_REQUIRED");if(!p.has("source_retrieved_at")||stamp(p.getString("source_retrieved_at"))!=p.optLong("received_at_ms",0)||p.optLong("received_at_ms",0)<=0)throw new IllegalArgumentException("SOURCE_RECEIPT_TIME_MISMATCH");if(p.optBoolean("test_only")&&!testOnly)throw new IllegalArgumentException("TEST_PROOF_IN_REAL_STORE");}
 private JSONObject registerLocked(JSONObject raw,JSONObject receipt,long now,long elapsed)throws Exception{String id=canonical(raw);JSONObject existing=registration(id);if(existing!=null)return new JSONObject(existing.toString()).put("registration_result","DUPLICATE");proof(receipt);if(!raw.optBoolean("source_identity_verified"))throw new IllegalArgumentException("SOURCE_IDENTITY_UNVERIFIED");JSONObject c=clock(receipt,now,elapsed);long post=stamp(raw.getString("scheduled_start")),at=c.getLong("trusted_now");String reason=(resultKnown(id)||raw.optBoolean("result_known")||raw.optString("data_status").contains("HISTORICAL"))?"RESULT_ALREADY_KNOWN":at>=post?"LATE_REGISTRATION":!c.getBoolean("verified")?"CLOCK_UNVERIFIED":"REGISTERED_PRE_RACE";boolean real=reason.equals("REGISTERED_PRE_RACE");JSONObject r=new JSONObject().put("record_type",real?"PROSPECTIVE_REGISTRATION":"REGISTRATION_DENIED").put("race_id",id).put("registered_at",Instant.ofEpochMilli(at).toString()).put("scheduled_post_time",raw.getString("scheduled_start")).put("source_retrieved_at",receipt.getString("source_retrieved_at")).put("source_raw_sha256",receipt.getString("raw_sha256")).put("source_record_id",receipt.getString("source_record_id")).put("source_receipt",new JSONObject(receipt.toString())).put("result_known",reason.equals("RESULT_ALREADY_KNOWN")).put("REAL_PROSPECTIVE",real).put("reason",reason).put("clock",c).put("race",new JSONObject(raw.toString()).put("race_id",id)).put("test_only",testOnly).put("realMoney","BLOCKED").put("data_status","READINESS_ONLY");String key=real?"REGISTER:"+id:"DENIED:"+id+":"+now;runtime.appendFetch(context(raw,real,false),key,r.toString(),runtime.fetchStatus().getString("head"));return r;}
 private JSONObject captureLocked(String id,String stage,JSONObject latest,JSONObject receipt,long now,long elapsed)throws Exception{JSONObject reg=registration(id);if(reg==null||!reg.getBoolean("REAL_PROSPECTIVE"))throw new IllegalStateException("NOT_PROSPECTIVE");JSONObject r=reg.getJSONObject("race");if(!reg.getString("scheduled_post_time").equals(latest.getString("scheduled_start")))throw new IllegalStateException("SCHEDULE_CHANGED");boolean identity=latest.optBoolean("source_identity_verified")&&canonical(latest).equals(id);for(String k:new String[]{"date","venue_code","venue","meeting","day","race_no"})identity=identity&&r.optString(k).equals(latest.optString(k));boolean roster=validRoster(r,latest);int index=Arrays.asList(STAGE).indexOf(stage);if(index<0)throw new IllegalArgumentException("MILESTONE_INVALID");if(latest.optString("data_status").contains("HISTORICAL")||latest.has("win_payout")||latest.has("finish_position"))throw new IllegalArgumentException("POST_RESULT_MARKET_FORBIDDEN");for(int h=0;h<latest.getJSONArray("runners").length();h++)if(latest.getJSONArray("runners").getJSONObject(h).has("final_win_odds"))throw new IllegalArgumentException("POST_RESULT_MARKET_FORBIDDEN");proof(receipt);JSONObject c=clock(receipt,now,elapsed);long post=stamp(reg.getString("scheduled_post_time")),at=c.getLong("trusted_now"),target=post-TARGET[index]*1000L;JSONArray runners=latest.getJSONArray("runners"),odds=new JSONArray(),rosterEvidence=new JSONArray();Set<Integer> seen=new HashSet<>();int active=0;boolean complete=true;for(int i=0;i<runners.length();i++){JSONObject h=runners.getJSONObject(i);rosterEvidence.put(new JSONObject().put("horse_number",h.getInt("horse_no")).put("scratched",h.optBoolean("scratched")).put("active",!h.optBoolean("scratched")));if(h.optBoolean("scratched"))continue;active++;int no=h.getInt("horse_no");if(no<1||no>18||!seen.add(no)){roster=false;continue;}double o=h.optDouble("win_odds",Double.NaN);if(!Double.isFinite(o)||o<1)complete=false;else odds.put(new JSONObject().put("horse_number",no).put("win_odds",o));}complete=complete&&active>=2&&odds.length()==active;if(complete){double sum=0;for(int i=0;i<odds.length();i++)sum+=1/odds.getJSONObject(i).getDouble("win_odds");for(int i=0;i<odds.length();i++){JSONObject x=odds.getJSONObject(i);int rank=1;for(int j=0;j<odds.length();j++)if(odds.getJSONObject(j).getDouble("win_odds")<x.getDouble("win_odds"))rank++;x.put("market_rank",rank).put("market_probability",(1/x.getDouble("win_odds"))/sum);}}String status=!identity?"SNAPSHOT_RACE_MISMATCH":!roster?"ROSTER_IDENTITY_INVALID":!c.getBoolean("verified")?"CLOCK_UNVERIFIED":(Math.abs(at-target)>TOLERANCE[index]*1000L||Math.abs(now-target)>TOLERANCE[index]*1000L)?"OUTSIDE_FIXED_TOLERANCE":!complete?"ODDS_INCOMPLETE":resultKnown(id)||at>=post?"RESULT_ALREADY_KNOWN":"PASS";JSONObject p=new JSONObject().put("race_id",id).put("milestone",stage).put("status",status).put("target_time",Instant.ofEpochMilli(target).toString()).put("REAL_PROSPECTIVE",true).put("source_identity_verified",identity).put("roster_identity_valid",roster).put("result_known",resultKnown(id)).put("race_started",at>=post).put("http_status",receipt.optInt("http_status")).put("raw_size",receipt.opt("raw_size")).put("source_uri",receipt.opt("source_uri")).put("http_date",receipt.opt("http_date")).put("received_at_ms",receipt.optLong("received_at_ms")).put("server_time_ms",receipt.optLong("server_time_ms")).put("received_at",receipt.getString("source_retrieved_at")).put("target_offset",TARGET[index]).put("tolerance_seconds",TOLERANCE[index]).put("target_error_ms",now-target).put("trusted_observed_at",Instant.ofEpochMilli(at).toString()).put("observed_at",Instant.ofEpochMilli(now).toString()).put("scheduled_post_time",reg.getString("scheduled_post_time")).put("odds",odds).put("roster",rosterEvidence).put("runner_count",active).put("odds_count",odds.length()).put("completeness",active==0?0:(double)odds.length()/active).put("source_raw_sha256",receipt.getString("raw_sha256")).put("source_record_id",receipt.getString("source_record_id")).put("source_retrieved_at",receipt.getString("source_retrieved_at")).put("clock_skew_ms",c.getLong("clock_skew_ms")).put("clock_verified",c.getBoolean("verified")).put("data_status","READINESS_ONLY").put("realMoney","BLOCKED").put("test_only",testOnly);String key="TC:"+id+":"+stage;JSONObject result=runtime.appendTimechain(context(r,true,false),key,p.toString(),runtime.timechainStatus().getString("head"));return result.put("snapshot",p);}
 private JSONObject shadowLocked(String id)throws Exception{JSONObject reg=registration(id);if(reg==null)throw new IllegalStateException("NOT_PROSPECTIVE");JSONObject r=reg.getJSONObject("race"),p=new JSONObject().put("race_id",id).put("model_applied",false).put("reason","F0_NOT_READY").put("STAKE_RULE",STAKE_RULE).put("REAL_PROSPECTIVE",true).put("test_only",testOnly).put("data_status","READINESS_ONLY").put("realMoney","BLOCKED");return runtime.appendShadow(context(r,true,false),"SHADOW:F0:"+id,p.toString(),runtime.shadowStatus().getString("head"));}
 private JSONObject resultLocked(String id,JSONObject result,JSONObject receipt)throws Exception{JSONObject reg=registration(id);if(reg==null)throw new IllegalStateException("NOT_PROSPECTIVE");proof(receipt);if(!id.equals(result.getString("race_id")))throw new IllegalArgumentException("RESULT_RACE_MISMATCH");if(!result.optBoolean("source_identity_verified")||result.getJSONArray("winner").length()==0||result.getJSONArray("win_payout").length()==0)throw new IllegalArgumentException("RESULT_UNVERIFIED");if(stamp(receipt.getString("source_retrieved_at"))<stamp(reg.getString("scheduled_post_time")))throw new IllegalArgumentException("RESULT_BEFORE_RACE");JSONObject p=new JSONObject(result.toString()).put("result_raw_sha256",receipt.getString("raw_sha256")).put("result_retrieved_at",receipt.getString("source_retrieved_at")).put("result_source",receipt.getString("source_record_id")).put("data_status","READINESS_ONLY").put("realMoney","BLOCKED");return runtime.appendResult(context(reg.getJSONObject("race"),true,true),"RESULT:"+id,p.toString(),runtime.resultStatus().getString("head"));}
 public JSONObject bankroll()throws Exception{JSONArray buys=rows("FORMAL_BUY"),settled=rows("SETTLEMENT");Map<String,JSONObject> tickets=new HashMap<>();long stake=0,payout=0,settledStake=0,todayStake=0,todayPayout=0,todaySettledStake=0;String today=LocalDate.now(ZoneId.of("Asia/Tokyo")).toString();Set<String> todayBuys=new HashSet<>();for(int i=0;i<buys.length();i++){JSONObject row=buys.getJSONObject(i),p=new JSONObject(row.getString("payload"));if(p.has("REAL_PROSPECTIVE")&&!p.getBoolean("REAL_PROSPECTIVE"))throw new IllegalStateException("HISTORICAL_BUY_IN_FORMAL_STORE");long n=p.getLong("stake_yen");if(n<0||n!=p.getDouble("stake_yen"))throw new IllegalStateException("STAKE_INVALID");stake=Math.addExact(stake,n);tickets.put(row.getString("key"),p);String date=Instant.parse(row.getString("created_at")).atZone(ZoneId.of("Asia/Tokyo")).toLocalDate().toString();if(today.equals(date)){todayStake+=n;todayBuys.add(row.getString("key"));}}Set<String> done=new HashSet<>();for(int i=0;i<settled.length();i++){JSONObject row=settled.getJSONObject(i);String key=row.getString("key").replaceFirst("^SETTLEMENT:","BUY:");if(!tickets.containsKey(key)||!done.add(key))throw new IllegalStateException("SETTLEMENT_BUY_MISMATCH");JSONObject p=new JSONObject(row.getString("payload"));long n=p.getLong("payout_yen");if(n<0||n!=p.getDouble("payout_yen"))throw new IllegalStateException("PAYOUT_INVALID");payout=Math.addExact(payout,n);settledStake+=tickets.get(key).getLong("stake_yen");String date=Instant.parse(row.getString("created_at")).atZone(ZoneId.of("Asia/Tokyo")).toLocalDate().toString();if(today.equals(date)){todayPayout+=n;todaySettledStake+=tickets.get(key).getLong("stake_yen");}}Set<String> skips=new HashSet<>();JSONArray shadowRows=rows("SHADOW");for(int i=0;i<shadowRows.length();i++){JSONObject p=new JSONObject(shadowRows.getJSONObject(i).getString("payload"));if("SKIP".equals(p.optString("decision_action"))&&"FORMAL".equals(p.optString("portfolio"))&&p.optBoolean("REAL_PROSPECTIVE"))skips.add(p.getString("race_id"));}return new JSONObject().put("test_only",testOnly).put("starting_bankroll",100000).put("current_bankroll",100000-stake+payout).put("stake",stake).put("payout",payout).put("profit_loss",payout-settledStake).put("today_stake",todayStake).put("today_payout",todayPayout).put("today_profit_loss",todayPayout-todaySettledStake).put("ROI",settledStake==0?JSONObject.NULL:(double)payout/settledStake).put("buy_count",buys.length()).put("skip_count",skips.size()).put("pending_count",buys.length()-done.size()).put("STAKE_RULE",STAKE_RULE).put("realMoney","BLOCKED");}
 public JSONObject register(JSONObject raw,JSONObject receipt,long now,long elapsed)throws Exception{synchronized(ProspectiveRuntime.class){return registerLocked(raw,receipt,now,elapsed);}}
 public JSONObject capture(String id,String stage,JSONObject latest,JSONObject receipt,long now,long elapsed)throws Exception{synchronized(ProspectiveRuntime.class){return captureLocked(id,stage,latest,receipt,now,elapsed);}}
 public JSONObject shadow(String id)throws Exception{synchronized(ProspectiveRuntime.class){return shadowLocked(id);}}
 public JSONObject result(String id,JSONObject result,JSONObject receipt)throws Exception{synchronized(ProspectiveRuntime.class){return resultLocked(id,result,receipt);}}
 public JSONObject unavailable(String id,String stage,String error,long now)throws Exception{synchronized(ProspectiveRuntime.class){JSONObject reg=registration(id);if(reg==null)throw new IllegalStateException("NOT_PROSPECTIVE");JSONObject existing=find("TIMECHAIN","TC:"+id+":"+stage);if(existing!=null)return new JSONObject().put("result","DUPLICATE");int i=Arrays.asList(STAGE).indexOf(stage);if(i<0)throw new IllegalArgumentException("MILESTONE_INVALID");JSONObject p=new JSONObject().put("race_id",id).put("milestone",stage).put("status","UNAVAILABLE").put("error_code",error==null?"SOURCE_UNAVAILABLE":error).put("target_offset",TARGET[i]).put("tolerance_seconds",TOLERANCE[i]).put("observed_at",Instant.ofEpochMilli(now).toString()).put("source_raw_sha256",JSONObject.NULL).put("source_record_id",reg.getString("source_record_id")).put("source_retrieved_at",JSONObject.NULL).put("scheduled_post_time",reg.getString("scheduled_post_time")).put("runner_count",JSONObject.NULL).put("odds_count",0).put("odds",new JSONArray()).put("completeness",JSONObject.NULL).put("clock_skew_ms",JSONObject.NULL).put("clock_verified",false).put("data_status","READINESS_ONLY").put("realMoney","BLOCKED");return runtime.appendTimechain(context(reg.getJSONObject("race"),true,false),"TC:"+id+":"+stage,p.toString(),runtime.timechainStatus().getString("head"));}}
 @Override public void close(){runtime.close();}
}
